head.b:skin:
* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #f8fafc;
  --surface: #ffffff;
  --surface-hover: #f1f5f9;
  --surface-2: #f8fafc;
  --text: #0f172a;
  --text-muted: #64748b;
  --border: #e2e8f0;
  --brand: #2563eb;
  --brand-hover: #1d4ed8;
  --brand-subtle: #eff6ff;
  --brand-gradient: linear-gradient(135deg, #2563eb 0%, #4f46e5 100%);
  --card-radius: 16px;
  --shadow-sm: 0 1px 3px rgba(15, 23, 42, 0.05);
  --shadow-card: 0 4px 20px -2px rgba(15, 23, 42, 0.06), 0 2px 6px -1px rgba(15, 23, 42, 0.04);
  --shadow-hover: 0 16px 32px -4px rgba(15, 23, 42, 0.12), 0 4px 12px -2px rgba(15, 23, 42, 0.06);
}

body.dark-mode {
  --bg: #090d16;
  --surface: #0f172a;
  --surface-hover: #1e293b;
  --surface-2: #141e33;
  --text: #f8fafc;
  --text-muted: #94a3b8;
  --border: #1e293b;
  --brand: #3b82f6;
  --brand-hover: #60a5fa;
  --brand-subtle: rgba(59, 130, 246, 0.15);
  --shadow-card: 0 4px 20px -2px rgba(0, 0, 0, 0.5);
  --shadow-hover: 0 16px 32px -4px rgba(0, 0, 0, 0.7);
}

body {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  padding-bottom: 85px;
  min-height: 100vh;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }

@keyframes srPulse {
  0%, 100% { opacity: 0.95; }
  50% { opacity: 0.35; }
}
@keyframes liveGlow {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.9); }
}

/* Top Strip */
.top-strip {
  background: #0f172a;
  color: #93c5fd;
  padding: 8px 16px;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.3px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.top-strip-left {
  display: flex;
  align-items: center;
  gap: 8px;
}
.live-dot {
  width: 8px;
  height: 8px;
  background: #22c55e;
  border-radius: 50%;
  box-shadow: 0 0 8px #22c55e;
  animation: liveGlow 1.8s infinite;
  display: inline-block;
}
.top-strip-right {
  display: flex;
  align-items: center;
  gap: 14px;
}
.top-strip-right a {
  color: #cbd5e1;
  font-size: 11.5px;
  transition: color 0.2s;
}
.top-strip-right a:hover {
  color: #ffffff;
}

/* Minimal Modern Header (Glassmorphic) */
.saas-header {
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
  transition: background 0.3s;
}
body.dark-mode .saas-header {
  background: rgba(15, 23, 42, 0.92);
}
.header-inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 12px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.brand-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
}
.brand-logo-img {
  height: 44px;
  width: auto;
  max-width: 240px;
  object-fit: contain;
  display: block;
  transition: transform 0.2s ease;
}
.brand-logo:hover .brand-logo-img {
  transform: scale(1.02);
}
body.dark-mode .brand-logo-img {
  filter: drop-shadow(0 0 2px rgba(255, 255, 255, 0.85));
}
.brand-badge-icon {
  display: none;
}
.header-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.nav-btn {
  padding: 7px 13px;
  font-size: 13px;
  font-weight: 700;
  border-radius: 8px;
  background: var(--surface-hover);
  color: var(--text-muted);
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.nav-btn:hover, .nav-btn.active {
  background: var(--brand);
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.2);
}
.nav-btn-highlight {
  background: var(--brand-gradient) !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25);
}
.theme-toggle-btn {
  background: var(--surface-hover);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 7px 12px;
  font-size: 13px;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  transition: background 0.2s;
}
.theme-toggle-btn:hover {
  background: var(--border);
}

/* Hero Search Area (Modern Navy Gradient) */
.hero-search-area {
  background: linear-gradient(135deg, #090e1c 0%, #152243 50%, #0c142b 100%);
  padding: 40px 20px 34px 20px;
  text-align: center;
  color: #ffffff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  position: relative;
}
.search-box-wrapper {
  max-width: 680px;
  margin: 0 auto;
  position: relative;
}
.search-input {
  width: 100%;
  padding: 16px 52px 16px 22px;
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: #ffffff;
  color: #0f172a;
  outline: none;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  transition: all 0.25s ease;
}
.search-input:focus {
  box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.4), 0 10px 30px rgba(0, 0, 0, 0.25);
  border-color: #60a5fa;
}
.search-icon {
  position: absolute;
  right: 18px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 19px;
  color: #64748b;
  pointer-events: none;
}
.search-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: var(--shadow-hover);
  max-height: 380px;
  overflow-y: auto;
  z-index: 9999;
  display: none;
  list-style: none;
  text-align: left;
  padding: 6px;
}
.search-dropdown li {
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 13.5px;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  transition: background 0.15s ease;
}
.search-dropdown li:hover { background: var(--surface-hover); }

/* Filter Chips Bar */
.filter-chips-container {
  max-width: 860px;
  margin: 20px auto 0 auto;
  display: flex;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: none;
  justify-content: center;
  padding-bottom: 2px;
}
.filter-chips-container::-webkit-scrollbar { display: none; }
@media (max-width: 860px) {
  .filter-chips-container { justify-content: flex-start; }
}
.chip-btn {
  padding: 7px 16px;
  border-radius: 20px;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(8px);
  color: #ffffff;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
}
.chip-btn:hover, .chip-btn.active {
  background: #ffffff;
  color: #0f172a !important;
  border-color: #ffffff;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
}

/* Main Container & Modern 5-Box Grid */
.main-container {
  max-width: 1240px;
  margin: 28px auto 40px auto;
  padding: 0 16px;
  min-height: 550px;
}

/* Row 1: 3 Modern Equal-Height Cards */
.cards-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
  margin-bottom: 28px;
  align-items: stretch;
}
/* Row 2: 2 Modern Equal-Height Cards */
.cards-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 22px;
  margin-bottom: 34px;
  align-items: stretch;
}

/* Mobile Reordering for Natural Student Priority */
@media (max-width: 880px) {
  .cards-grid-3 {
    display: flex !important;
    flex-direction: column !important;
    gap: 20px;
  }
  .cards-grid-2 {
    display: flex !important;
    flex-direction: column !important;
    gap: 20px;
  }
  .card-order-job { order: 1 !important; }
  .card-order-adm { order: 2 !important; }
  .card-order-res { order: 3 !important; }
}

.feed-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
  height: 100%;
}
.feed-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
  border-color: #cbd5e1;
}
body.dark-mode .feed-card:hover {
  border-color: #334155;
}

.card-head {
  padding: 14px 18px;
  border-bottom: 1px solid var(--border);
  font-size: 15.5px;
  font-weight: 800;
  letter-spacing: -0.3px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--surface);
}
.head-res { border-top: 4px solid #dc2626; color: #dc2626; }
.head-adm { border-top: 4px solid #2563eb; color: #2563eb; }
.head-job { border-top: 4px solid #16a34a; color: #16a34a; }
.head-key { border-top: 4px solid #9333ea; color: #9333ea; }
.head-syl { border-top: 4px solid #ea580c; color: #ea580c; }

.head-count-badge {
  font-size: 11px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 10px;
  background: var(--surface-hover);
  color: var(--text-muted);
}

.card-body-list {
  list-style: none;
  padding: 8px 12px;
  min-height: 380px;
  max-height: 480px;
  overflow-y: auto;
  scrollbar-width: thin;
  flex-grow: 1;
}
.card-body-list::-webkit-scrollbar {
  width: 5px;
}
.card-body-list::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 4px;
}
.card-body-list li {
  padding: 9px 8px;
  border-bottom: 1px solid #f1f5f9;
  font-size: 13.5px;
  line-height: 1.5;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  transition: all 0.15s ease;
  position: relative;
}
body.dark-mode .card-body-list li { border-bottom-color: #1e293b; }
.card-body-list li:hover {
  background: var(--surface-hover);
  border-radius: 8px;
  transform: translateX(3px);
}
.card-body-list li a {
  flex: 1;
  font-weight: 600;
  color: var(--text);
  transition: color 0.15s;
}
.card-body-list li:hover a {
  color: var(--brand);
}

/* Department Badges */
.org-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 5px;
  letter-spacing: 0.3px;
  text-transform: uppercase;
  white-space: nowrap;
  margin-top: 2px;
  flex-shrink: 0;
}
.badge-ssc { background: #dbeafe; color: #1e40af; }
.badge-rrb { background: #dcfce7; color: #166534; }
.badge-police { background: #fef3c7; color: #92400e; }
.badge-bank { background: #f3e8ff; color: #6b21a8; }
.badge-upsc { background: #fee2e2; color: #991b1b; }
.badge-default { background: #f1f5f9; color: #475569; }

body.dark-mode .badge-ssc { background: rgba(30, 64, 175, 0.3); color: #93c5fd; }
body.dark-mode .badge-rrb { background: rgba(22, 101, 52, 0.3); color: #86efac; }
body.dark-mode .badge-police { background: rgba(146, 64, 14, 0.3); color: #fde68a; }
body.dark-mode .badge-bank { background: rgba(107, 33, 168, 0.3); color: #d8b4fe; }
body.dark-mode .badge-upsc { background: rgba(153, 27, 27, 0.3); color: #fca5a5; }
body.dark-mode .badge-default { background: #1e293b; color: #94a3b8; }

.urgency-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 4px;
  margin-left: 4px;
  white-space: nowrap;
  flex-shrink: 0;
}
.urgency-ending {
  background: #fee2e2;
  color: #b91c1c;
  border: 1px solid #fca5a5;
}
body.dark-mode .urgency-ending {
  background: rgba(185, 28, 28, 0.3);
  color: #fca5a5;
  border-color: rgba(248, 113, 113, 0.4);
}

.btn-item-share {
  opacity: 0;
  background: transparent;
  border: none;
  font-size: 13px;
  color: #25d366;
  cursor: pointer;
  padding: 0 4px;
  transition: opacity 0.15s, transform 0.15s;
}
.card-body-list li:hover .btn-item-share {
  opacity: 1;
  transform: scale(1.15);
}

.card-footer-box {
  padding: 11px 18px;
  border-top: 1px solid var(--border);
  background: var(--surface-2);
  text-align: right;
}
.btn-more-link {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--brand);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap 0.15s;
}
.btn-more-link:hover {
  gap: 7px;
  text-decoration: underline;
}

/* Centered Age Calculator Frame */
.calc-container {
  max-width: 860px;
  margin: 38px auto;
  padding: 30px 24px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  box-shadow: var(--shadow-card);
  text-align: center;
}
.calc-title {
  font-size: 21px;
  font-weight: 900;
  margin-bottom: 6px;
  color: var(--text);
}
.calc-subtitle {
  font-size: 13.5px;
  color: var(--text-muted);
  margin-bottom: 24px;
}
.calc-fields {
  display: flex;
  gap: 16px;
  align-items: flex-end;
  flex-wrap: wrap;
  justify-content: center;
}
.field-box {
  flex: 1;
  min-width: 220px;
  text-align: left;
}
.field-box label {
  display: block;
  font-size: 12.5px;
  font-weight: 700;
  margin-bottom: 6px;
  color: var(--text);
}
.field-box input {
  width: 100%;
  padding: 11px 14px;
  border: 1px solid var(--border);
  background: var(--surface-hover);
  color: var(--text);
  border-radius: 10px;
  font-family: inherit;
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.field-box input:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}
.btn-calculate {
  background: var(--brand);
  color: #ffffff;
  padding: 12px 24px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 800;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25);
}
.btn-calculate:hover {
  background: var(--brand-hover);
  transform: translateY(-1px);
}

/* Single Post & Static Content */
.content-card-box {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  padding: 34px;
  margin: 24px auto;
  max-width: 960px;
  box-shadow: var(--shadow-sm);
}
.content-title {
  font-size: 26px;
  font-weight: 900;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 14px;
  color: var(--brand);
  line-height: 1.35;
}
.content-body-area {
  font-size: 15.5px;
  line-height: 1.8;
  color: var(--text);
}
.content-body-area table {
  width: 100%;
  border-collapse: collapse;
  margin: 20px 0;
  border-radius: 8px;
  overflow: hidden;
}
.content-body-area th, .content-body-area td {
  border: 1px solid var(--border);
  padding: 11px 14px;
}
/* Table Headers & Quick Overview Card High-Contrast Fix */
.content-body-area table thead tr,
.content-body-area table tr[style*="color: #ffffff"],
.content-body-area table tr[style*="color:#ffffff"] {
  background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 100%) !important;
  color: #ffffff !important;
}
.content-body-area table th {
  background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 100%) !important;
  color: #ffffff !important;
  font-weight: 800 !important;
  font-size: 15.5px !important;
  padding: 12px 16px !important;
  border: 1px solid #1d4ed8 !important;
  letter-spacing: 0.2px;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35) !important;
}
body.dark-mode .content-body-area table th {
  background: linear-gradient(135deg, #0f172a 0%, #1e3a8a 100%) !important;
  border-color: #3b82f6 !important;
  color: #ffffff !important;
}
.content-body-area table td {
  color: var(--text);
  background: var(--surface);
}
.content-body-area table td[style*="background: #f8fafc"],
.content-body-area table td[style*="background:#f8fafc"] {
  background: var(--surface-hover) !important;
  color: var(--text) !important;
}
body.dark-mode .content-body-area div[style*="background: #ffffff"],
body.dark-mode .content-body-area div[style*="background:#ffffff"] {
  background: transparent !important;
  color: var(--text) !important;
}
/* Prevent duplicate title if post body already includes an h1 heading */
.content-body-area > div > h1:first-child,
.content-body-area > h1:first-child {
  display: none;
}

/* Featured Recruitment Banner */
.post-featured-banner {
  margin: 14px auto 24px auto;
  text-align: center;
  max-width: 100%;
}
.post-featured-banner img {
  width: 100%;
  max-width: 900px;
  height: auto;
  border-radius: 14px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  border: 1px solid var(--border);
  display: block;
  margin: 0 auto;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.post-featured-banner img:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.18);
}
body.dark-mode .post-featured-banner img {
  border-color: rgba(255, 255, 255, 0.1);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

/* Mobile App Bottom Floating Dock */
.mobile-dock {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-top: 1px solid var(--border);
  box-shadow: 0 -4px 18px rgba(0, 0, 0, 0.08);
  z-index: 999;
  padding: 8px 12px max(8px, env(safe-area-inset-bottom));
  justify-content: space-around;
  align-items: center;
}
body.dark-mode .mobile-dock {
  background: rgba(15, 23, 42, 0.94);
}
@media (max-width: 768px) {
  .mobile-dock { display: flex; }
  .header-nav { display: none; }
}
.dock-tab {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  cursor: pointer;
}
.dock-tab:hover, .dock-tab.active { color: var(--brand); }
/* ==========================================
   SOCIAL MEDIA SHARING ENGINE
   ========================================== */
.post-share-bar {
  margin: 18px 0 24px 0;
  padding: 12px 18px;
  background: var(--surface-hover);
  border: 1px solid var(--border);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
.share-bar-label {
  font-size: 13.5px;
  font-weight: 700;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 6px;
}
.share-btn-group {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.share-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 700;
  padding: 7px 14px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  text-decoration: none;
  color: #ffffff;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
}
.share-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.15);
  filter: brightness(1.08);
  color: #ffffff !important;
}
.share-btn:active {
  transform: translateY(0);
}

/* Platform Color Tokens */
.btn-wa {
  background: #25d366;
  box-shadow: 0 3px 10px rgba(37, 211, 102, 0.3);
}
.btn-fb {
  background: #1877f2;
  box-shadow: 0 3px 10px rgba(24, 119, 242, 0.3);
}
.btn-tg {
  background: #229ed9;
  box-shadow: 0 3px 10px rgba(34, 158, 217, 0.3);
}
.btn-ig {
  background: linear-gradient(45deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%);
  box-shadow: 0 3px 10px rgba(220, 39, 67, 0.35);
}
.btn-copy {
  background: var(--surface);
  color: var(--text) !important;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
}
.btn-copy:hover {
  background: var(--surface-hover);
  color: var(--brand) !important;
  border-color: var(--brand);
}
body.dark-mode .btn-copy {
  background: #1e293b;
  color: #f8fafc !important;
  border-color: #334155;
}
body.dark-mode .btn-copy:hover {
  background: #334155;
  color: #60a5fa !important;
  border-color: #60a5fa;
}
.share-btn svg {
  width: 17px;
  height: 17px;
  fill: currentColor;
  display: inline-block;
  vertical-align: middle;
  flex-shrink: 0;
}

/* Bottom Share CTA Box */
.post-share-cta-box {
  margin: 38px 0 20px 0;
  padding: 24px;
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.05) 0%, rgba(79, 70, 229, 0.08) 100%);
  border: 1.5px solid rgba(37, 99, 235, 0.22);
  border-radius: 14px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
body.dark-mode .post-share-cta-box {
  background: rgba(37, 99, 235, 0.12);
  border-color: rgba(59, 130, 246, 0.3);
}
.share-cta-header {
  display: flex;
  align-items: center;
  gap: 14px;
}
.share-cta-icon {
  font-size: 32px;
  line-height: 1;
}
.share-cta-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--text);
  margin: 0 0 3px 0;
}
.share-cta-subtitle {
  font-size: 13px;
  color: var(--text-muted);
  margin: 0;
}
.share-btn-lg {
  padding: 9px 16px;
  font-size: 13px;
}
@media (max-width: 600px) {
  .post-share-bar {
    flex-direction: column;
    align-items: flex-start;
  }
  .share-btn-group {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }
  .share-btn {
    justify-content: center;
  }
  .share-btn.btn-copy {
    grid-column: span 2;
  }
}

/* Footer Centered Clean Alignment */
.saas-footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  text-align: center;
  padding: 34px 15px;
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 50px;
}
.saas-footer a {
  color: var(--text-muted);
  margin: 0 10px;
  font-weight: 600;
  transition: color 0.15s;
}
.saas-footer a:hover { color: var(--brand); }

div.script:
//
document.addEventListener('DOMContentLoaded', function() {
  const btn = document.getElementById('calcAgeBtn');
  if (btn) {
    btn.addEventListener('click', function() {
      const dobVal = document.getElementById('calcDob').value;
      const cutoffVal = document.getElementById('calcCutoff').value;
      const resultBox = document.getElementById('calcResultDisplay');
      const resultText = document.getElementById('calcResultText');

      if (!dobVal || !cutoffVal) {
        alert('Kripya Date of Birth aur Cut-off Date dono select karein.');
        return;
      }

      const birthDate = new Date(dobVal);
      const targetDate = new Date(cutoffVal);

      if (birthDate > targetDate) {
        alert('Date of Birth cut-off date se pehle ki honi chahiye.');
        return;
      }

      let years = targetDate.getFullYear() - birthDate.getFullYear();
      let months = targetDate.getMonth() - birthDate.getMonth();
      let days = targetDate.getDate() - birthDate.getDate();

      if (days < 0) {
        months--;
        const prevMonth = new Date(targetDate.getFullYear(), targetDate.getMonth(), 0);
        days += prevMonth.getDate();
      }

      if (months < 0) {
        years--;
        months += 12;
      }

      resultText.innerText = years + ' Saal, ' + months + ' Mahine, ' + days + ' Din';
      resultBox.style.display = 'block';
    });
  }
});
//

body.script:
//
var globalAllPosts = [];
var rawFeedEntries = [];

// 1. High-Performance Client-Side Caching (0ms Instant Load)
function getCache(key) {
  try {
    var raw = sessionStorage.getItem(key);
    if (!raw) return null;
    var parsed = JSON.parse(raw);
    if (Date.now() - parsed.ts < 300000) { // 5-minute validity
      return parsed.val;
    }
  } catch(e) {}
  return null;
}

function setCache(key, val) {
  try {
    sessionStorage.setItem(key, JSON.stringify({ ts: Date.now(), val: val }));
  } catch(e) {}
}

// 2. Animated Skeleton Preloaders (Prevents blank white box effect)
function injectSkeletons() {
  var lists = ['list-result', 'list-admit', 'list-job', 'list-key', 'list-syl'];
  var skelHtml = '';
  for (var i = 0; i < 6; i++) {
    skelHtml += '<li style="padding:10px 4px; display:flex; align-items:center; gap:8px;">' +
                '<span style="display:inline-block; width:45px; height:20px; background:#e2e8f0; border-radius:4px; animation:srPulse 1.2s infinite ease-in-out;"></span>' +
                '<span style="display:inline-block; width:' + (60 + (i % 4) * 10) + '%; height:16px; background:#f1f5f9; border-radius:4px; animation:srPulse 1.2s infinite ease-in-out;"></span>' +
                '</li>';
  }
  lists.forEach(function(id) {
    var el = document.getElementById(id);
    if (el && el.children.length === 0) {
      el.innerHTML = skelHtml;
    }
  });
}

// Helper: Normalize Path for exact URL comparison
function normalizePath(u) {
  if (!u) return '';
  try {
    var parsed = new URL(u, window.location.origin);
    return parsed.pathname.toLowerCase().replace(/\/+$/, '');
  } catch(e) {
    return u.toLowerCase().split('?')[0].replace(/\/+$/, '');
  }
}

// Resizer Tool Page Visibility
(function checkResizerPage() {
  if (window.location.pathname.indexOf('/p/photo-signature-resizer') !== -1) {
    var rBox = document.getElementById('resizer-tool-wrapper');
    if (rBox) rBox.style.display = 'block';
  }
})();

// 3. Theme Controller (Dark Mode)
function applySavedTheme() {
  try {
    var saved = localStorage.getItem('sr_dark_mode');
    var body = document.body;
    var icon = document.getElementById('theme-icon');
    if (saved === 'enabled') {
      body.classList.add('dark-mode');
      if (icon) icon.innerText = '☀️';
    } else {
      body.classList.remove('dark-mode');
      if (icon) icon.innerText = '🌙';
    }
  } catch(e) {}
}

function toggleTheme() {
  var body = document.body;
  var isDark = body.classList.contains('dark-mode');
  localStorage.setItem('sr_dark_mode', isDark ? 'disabled' : 'enabled');
  applySavedTheme();
}
applySavedTheme();

// 4. Age Calculator Anchor Scroll Handler
function handleAgeCalculator(e) {
  if (window.location.pathname === '/' || window.location.pathname === '') {
    var el = document.getElementById('ageCalculator');
    if (el) {
      e.preventDefault();
      el.scrollIntoView({ behavior: 'smooth' });
    }
  }
}

// 5. Smart Badge & Department Detection
function getSmartBadges(title) {
  var t = title.toUpperCase();
  var org = '';
  var urgency = '';

  if (t.indexOf('SSC') > -1) org = '<span class="org-badge badge-ssc">SSC</span>';
  else if (t.indexOf('RAILWAY') > -1 || t.indexOf('RRB') > -1) org = '<span class="org-badge badge-rrb">RRB</span>';
  else if (t.indexOf('POLICE') > -1 || t.indexOf('CONSTABLE') > -1 || t.indexOf('BSF') > -1 || t.indexOf('AIRFORCE') > -1) org = '<span class="org-badge badge-police">DEFENCE</span>';
  else if (t.indexOf('BANK') > -1 || t.indexOf('IBPS') > -1 || t.indexOf('SBI') > -1) org = '<span class="org-badge badge-bank">BANK</span>';
  else if (t.indexOf('UPSC') > -1 || t.indexOf('BPSC') > -1 || t.indexOf('MPPSC') > -1 || t.indexOf('HPSC') > -1 || t.indexOf('RPSC') > -1 || t.indexOf('UPSSSC') > -1) org = '<span class="org-badge badge-upsc">PSC</span>';
  else org = '<span class="org-badge badge-default">GOVT</span>';

  if (t.indexOf('LAST DATE') > -1 || t.indexOf('ENDING') > -1 || t.indexOf('OUT') > -1) {
    urgency = '<span class="urgency-badge urgency-ending">⏳ Live</span>';
  }
  return { org: org, urgency: urgency };
}

// ==========================================
// SOCIAL MEDIA SHARING ENGINE (v2.0)
// ==========================================
// SOCIAL MEDIA SHARING ENGINE (v2.0)
// Supports: WhatsApp, Facebook, Telegram, Instagram
// ==========================================
function sharePostTo(platform) {
  var url = window.location.href.split('#')[0];
  var titleEl = document.querySelector('.content-title');
  var title = titleEl ? titleEl.innerText : document.title;
  title = title.replace(/\s+/g, ' ').trim();

  var text = '🔥 ' + title + '\n\nCheck official details, syllabus & online form here:\n' + url;

  if (platform === 'whatsapp') {
    window.open('https://api.whatsapp.com/send?text=' + encodeURIComponent(text), '_blank');
  } else if (platform === 'facebook') {
    window.open('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(url), '_blank');
  } else if (platform === 'telegram') {
    window.open('https://t.me/share/url?url=' + encodeURIComponent(url) + '&text=' + encodeURIComponent('🔥 ' + title), '_blank');
  } else if (platform === 'instagram') {
    if (navigator.share && /android|iphone|ipad|mobile/i.test(navigator.userAgent)) {
      navigator.share({ title: title, text: text, url: url }).catch(function() {});
    } else {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url);
      }
      alert('Post link copy ho gaya hai! Ab aap ise Instagram DM ya Story me share kar sakte hain.');
      window.open('https://www.instagram.com/', '_blank');
    }
  } else if (platform === 'native') {
    if (navigator.share) {
      navigator.share({ title: title, text: title, url: url }).catch(function() {});
    } else {
      window.open('https://api.whatsapp.com/send?text=' + encodeURIComponent(text), '_blank');
    }
  }
}

function copyPostUrl(btnEl) {
  var url = window.location.href.split('#')[0];
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(function() {
      showCopiedFeedback(btnEl);
    }).catch(function() {
      fallbackCopy(url, btnEl);
    });
  } else {
    fallbackCopy(url, btnEl);
  }
}

function fallbackCopy(text, btnEl) {
  var ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand('copy');
    showCopiedFeedback(btnEl);
  } catch(e) {}
  document.body.removeChild(ta);
}

function showCopiedFeedback(btnEl) {
  if (!btnEl) return;
  var textSpan = btnEl.querySelector('.copy-btn-text') || btnEl;
  var oldText = textSpan.innerText;
  textSpan.innerText = 'Copied! ✔';
  btnEl.style.background = '#22c55e';
  btnEl.style.color = '#ffffff';
  btnEl.style.borderColor = '#16a34a';
  setTimeout(function() {
    textSpan.innerText = oldText;
    btnEl.style.background = '';
    btnEl.style.color = '';
    btnEl.style.borderColor = '';
  }, 2200);
}

// Quick WhatsApp Share Helper for list items
function shareToWhatsApp(title, link) {
  var fullUrl = link.indexOf('http') === 0 ? link : (window.location.origin + link);
  var text = '🔥 Check this update: ' + title + '\n\n🔗 Link: ' + fullUrl;
  window.open('https://api.whatsapp.com/send?text=' + encodeURIComponent(text), '_blank');
}

// 6. Interactive Quick Filter Chips Handler
window.filterFeed = function(tag, btnEl) {
  document.querySelectorAll('.chip-btn').forEach(function(b) { b.classList.remove('active'); });
  if (btnEl) btnEl.classList.add('active');
  renderHomepageBoxes(tag);
};

function renderHomepageBoxes(filterTag) {
  var resList = document.getElementById('list-result');
  var admList = document.getElementById('list-admit');
  var jobList = document.getElementById('list-job');
  var keyList = document.getElementById('list-key');
  var sylList = document.getElementById('list-syl');

  if (!resList || !admList || !jobList) return;

  var resHtml = '', admHtml = '', jobHtml = '', keyHtml = '', sylHtml = '';
  var cRes = 0, cAdm = 0, cJob = 0, cKey = 0, cSyl = 0;

  rawFeedEntries.forEach(function(p) {
    var tl = p.title.toUpperCase();

    if (filterTag && filterTag !== 'ALL') {
      if (filterTag === 'SSC' && tl.indexOf('SSC') === -1) return;
      if (filterTag === 'RAILWAY' && tl.indexOf('RAILWAY') === -1 && tl.indexOf('RRB') === -1) return;
      if (filterTag === 'POLICE' && tl.indexOf('POLICE') === -1 && tl.indexOf('CONSTABLE') === -1 && tl.indexOf('BSF') === -1 && tl.indexOf('AIRFORCE') === -1) return;
      if (filterTag === 'BANK' && tl.indexOf('BANK') === -1 && tl.indexOf('IBPS') === -1 && tl.indexOf('SBI') === -1) return;
      if (filterTag === '10TH' && tl.indexOf('10TH') === -1 && tl.indexOf('12TH') === -1 && tl.indexOf('INTER') === -1 && tl.indexOf('MATRIC') === -1) return;
    }

    var badges = getSmartBadges(p.title);
    var safeTitle = p.title.replace(/'/g, "\\'");
    var item = '<li>' + badges.org + 
               '<a href="' + p.link + '">' + p.title + '</a>' + 
               badges.urgency +
               '<button class="btn-item-share" onclick="shareToWhatsApp(\'' + safeTitle + '\', \'' + p.link + '\')" title="Share to WhatsApp">💬</button>' +
               '</li>';

    if (p.cat === 'Answer Key') {
      if (cKey < 15) { keyHtml += item; cKey++; }
    } else if (p.cat === 'Syllabus') {
      if (cSyl < 15) { sylHtml += item; cSyl++; }
    } else if (p.cat === 'Result') {
      if (cRes < 20) { resHtml += item; cRes++; }
    } else if (p.cat === 'Admit Card') {
      if (cAdm < 20) { admHtml += item; cAdm++; }
    } else {
      if (cJob < 20) { jobHtml += item; cJob++; }
    }
  });

  resList.innerHTML = resHtml || '<li style="color:#64748b;">No updates found.</li>';
  admList.innerHTML = admHtml || '<li style="color:#64748b;">No updates found.</li>';
  jobList.innerHTML = jobHtml || '<li style="color:#64748b;">No updates found.</li>';
  if (keyList) keyList.innerHTML = keyHtml || '<li style="color:#64748b;">No updates found.</li>';
  if (sylList) sylList.innerHTML = sylHtml || '<li style="color:#64748b;">No updates found.</li>';
}

// 7. Live Search Engine
function setupLiveSearch() {
  var input = document.getElementById('site-search-input');
  var list = document.getElementById('search-results-list');
  if (!input || !list) return;

  input.addEventListener('input', function() {
    var query = this.value.trim().toLowerCase();
    if (query.length < 2) {
      list.style.display = 'none';
      list.innerHTML = '';
      return;
    }

    var matched = [];
    for (var i = 0; i < globalAllPosts.length; i++) {
      var p = globalAllPosts[i];
      if (p.title.toLowerCase().indexOf(query) > -1) {
        matched.push(p);
        if (matched.length >= 8) break;
      }
    }

    if (matched.length > 0) {
      var html = '';
      for (var j = 0; j < matched.length; j++) {
        var badges = getSmartBadges(matched[j].title);
        html += '<li onclick="window.location.href=\'' + matched[j].link + '\'">' +
                  badges.org +
                  '<span style="flex:1;">' + matched[j].title + '</span>' +
                '</li>';
      }
      list.innerHTML = html;
      list.style.display = 'block';
    } else {
      list.innerHTML = '<li style="color:#64748b;text-align:center;">No matching vacancy found</li>';
      list.style.display = 'block';
    }
  });

  document.addEventListener('click', function(e) {
    if (!e.target.closest('.search-box-wrapper')) {
      list.style.display = 'none';
    }
  });
}

// 8. MAIN PORTAL CONTROLLER
(function() {
  var currentPath = normalizePath(window.location.pathname);
  var isSinglePost = currentPath.indexOf('.html') > -1 && currentPath.indexOf('/p/') === -1;
  var isStaticPage = currentPath.indexOf('/p/') > -1 && currentPath.indexOf('photo-signature-resizer') === -1;
  var isLabelPage = window.location.pathname.indexOf('/search/label/') > -1;

  // STATIC PAGES (About, Disclaimer, Privacy Policy)
  if (isStaticPage) {
    var directBox = document.getElementById('direct-post-display');
    var cachedPage = getCache('page_' + currentPath);
    if (cachedPage && directBox) {
      directBox.innerHTML = cachedPage;
      setupLiveSearch();
      return;
    }

    fetch('/feeds/pages/default?alt=json')
      .then(function(res) { return res.json(); })
      .then(function(data) {
        var entries = data.feed.entry || [];
        var matched = null;
        for (var i = 0; i < entries.length; i++) {
          var links = entries[i].link || [];
          for (var j = 0; j < links.length; j++) {
            if (links[j].rel === 'alternate' && normalizePath(links[j].href) === currentPath) {
              matched = entries[i];
              break;
            }
          }
          if (matched) break;
        }

        if (matched && directBox) {
          var pTitle = matched.title ? matched.title.$t : '';
          var pContent = matched.content ? matched.content.$t : (matched.summary ? matched.summary.$t : '');
          var rendered = '<div class="content-card-box">' +
                         '<h1 class="content-title">' + pTitle + '</h1>' +
                         '<div class="content-body-area">' + pContent + '</div>' +
                         '</div>';
          directBox.innerHTML = rendered;
          setCache('page_' + currentPath, rendered);
        }
      })
      .catch(function() {});
    setupLiveSearch();
    return;
  }

  // Helper: Parse raw entries into clean post objects
  function parseFeedEntries(entries) {
    var blocked = ['contact us', 'privacy policy', 'disclaimer', 'about us', 'admission', 'latest job', 'admit card', 'result', 'syllabus', 'answer key', 'sarkari result'];
    var list = [];
    (entries || []).forEach(function(entry) {
      var title = (entry.title && entry.title.$t ? entry.title.$t : '').trim();
      var tl = title.toLowerCase();
      for (var b = 0; b < blocked.length; b++) {
        if (tl === blocked[b] || tl === blocked[b] + '™') return;
      }
      if (title.length < 15) return;

      var link = '#';
      var links = entry.link || [];
      for (var i = 0; i < links.length; i++) {
        if (links[i].rel === 'alternate') { link = links[i].href; break; }
      }

      var cats = (entry.category || []).map(function(c) {
        return (c.term || '').toLowerCase().trim();
      });

      var primaryCat = 'Job';
      if (cats.indexOf('answer key') > -1 || tl.indexOf('answer key') > -1) primaryCat = 'Answer Key';
      else if (cats.indexOf('syllabus') > -1 || tl.indexOf('syllabus') > -1) primaryCat = 'Syllabus';
      else if (cats.indexOf('result') > -1 || tl.indexOf('result') > -1) primaryCat = 'Result';
      else if (cats.indexOf('admit card') > -1 || tl.indexOf('admit card') > -1 || tl.indexOf('exam date') > -1) primaryCat = 'Admit Card';

      list.push({ title: title, link: link, cat: primaryCat, categories: cats });
    });
    return list;
  }

  // Live Category Counts Updater
  function updateCategoryLiveCounts(posts) {
    var counts = { Result: 0, 'Admit Card': 0, Job: 0, 'Answer Key': 0, Syllabus: 0 };
    (posts || []).forEach(function(p) {
      if (counts[p.cat] !== undefined) counts[p.cat]++;
      else counts.Job++;
    });
    var bRes = document.getElementById('badge-count-res');
    var bAdm = document.getElementById('badge-count-adm');
    var bJob = document.getElementById('badge-count-job');
    var bKey = document.getElementById('badge-count-key');
    var bSyl = document.getElementById('badge-count-syl');
    if (bRes) bRes.innerText = counts.Result + ' Live';
    if (bAdm) bAdm.innerText = counts['Admit Card'] + ' Live';
    if (bJob) bJob.innerText = counts.Job + ' Live';
    if (bKey) bKey.innerText = counts['Answer Key'] + ' Live';
    if (bSyl) bSyl.innerText = counts.Syllabus + ' Live';
  }

  // Progressive Multi-Batch Loader for ALL 400+ Posts
  function loadAllPostsProgressively(onFirstBatch, onProgress, onAllDone) {
    var cached = getCache('sr_all_posts_v4');
    if (cached && cached.length >= 350) {
      globalAllPosts = cached;
      rawFeedEntries = cached;
      if (onFirstBatch) onFirstBatch(cached);
      updateCategoryLiveCounts(cached);
      if (onAllDone) onAllDone(cached);
      return;
    }

    var accumulated = [];
    function fetchBatch(startIndex) {
      fetch('/feeds/posts/summary?alt=json&start-index=' + startIndex + '&max-results=100')
        .then(function(res) { return res.json(); })
        .then(function(data) {
          var raw = (data.feed && data.feed.entry) ? data.feed.entry : [];
          var parsed = parseFeedEntries(raw);
          accumulated = accumulated.concat(parsed);

          globalAllPosts = accumulated;
          rawFeedEntries = accumulated;

          if (startIndex === 1) {
            if (onFirstBatch) onFirstBatch(accumulated);
          } else {
            if (onProgress) onProgress(accumulated);
          }
          updateCategoryLiveCounts(accumulated);

          if (raw.length >= 90) {
            fetchBatch(startIndex + raw.length);
          } else {
            setCache('sr_all_posts_v4', accumulated);
            if (onAllDone) onAllDone(accumulated);
          }
        })
        .catch(function(err) {
          if (accumulated.length > 0) {
            setCache('sr_all_posts_v4', accumulated);
            if (onAllDone) onAllDone(accumulated);
          }
        });
    }
    fetchBatch(1);
  }

  // SINGLE POST LOADER
  if (isSinglePost) {
    var nativePost = document.getElementById('native-post-box');
    if (nativePost && (nativePost.innerText.length > 30 || nativePost.children.length > 0)) {
      // Native Blogger template renders post server-side with 0 network latency!
      loadAllPostsProgressively(); // Pre-load global index for search in background
      setupLiveSearch();
      return;
    }

    var directBox = document.getElementById('direct-post-display');
    var cachedPost = getCache('post_' + currentPath);

    if (cachedPost && directBox) {
      directBox.innerHTML = cachedPost;
      loadAllPostsProgressively();
      setupLiveSearch();
      return;
    }

    function searchFeed(maxResults) {
      return fetch('/feeds/posts/default?alt=json&max-results=' + maxResults)
        .then(function(res) { return res.json(); })
        .then(function(data) {
          var entries = data.feed.entry || [];
          var matched = null;
          for (var i = 0; i < entries.length; i++) {
            var links = entries[i].link || [];
            for (var j = 0; j < links.length; j++) {
              if (links[j].rel === 'alternate' && normalizePath(links[j].href) === currentPath) {
                matched = entries[i];
                break;
              }
            }
            if (matched) break;
          }
          return matched;
        });
    }

    searchFeed(100).then(function(matched) {
      if (matched && directBox) {
        var pTitle = matched.title ? matched.title.$t : '';
        var pContent = matched.content ? matched.content.$t : (matched.summary ? matched.summary.$t : '');
        var waSvg = '<svg class="share-svg" fill="currentColor" height="16" viewBox="0 0 24 24" width="16"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/></svg>';
        var fbSvg = '<svg class="share-svg" fill="currentColor" height="16" viewBox="0 0 24 24" width="16"><path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z"/></svg>';
        var tgSvg = '<svg class="share-svg" fill="currentColor" height="16" viewBox="0 0 24 24" width="16"><path d="M12 0C5.373 0 0 5.373 0 12s5.373 12 12 12 12-5.373 12-12S18.627 0 12 0zm5.894 8.221l-1.97 9.28c-.145.658-.537.818-1.084.508l-3-2.21-1.446 1.394c-.16.16-.295.295-.605.295l.213-3.053 5.56-5.023c.242-.213-.054-.333-.373-.121l-6.871 4.326-2.962-.924c-.643-.204-.657-.643.136-.953l11.57-4.461c.537-.197 1.006.128.832.946z"/></svg>';
        var igSvg = '<svg class="share-svg" fill="currentColor" height="16" viewBox="0 0 24 24" width="16"><path d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zm0-2.163c-3.259 0-3.667.014-4.947.072-4.358.2-6.78 2.618-6.98 6.98-.059 1.281-.073 1.689-.073 4.948 0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98 1.281.058 1.689.072 4.948.072 3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98-1.281-.059-1.69-.073-4.949-.073zm0 5.838c-3.403 0-6.162 2.759-6.162 6.162s2.759 6.163 6.162 6.163 6.162-2.759 6.162-6.163c0-3.403-2.759-6.162-6.162-6.162zm0 10.162c-2.209 0-4-1.79-4-4 0-2.209 1.791-4 4-4s4 1.791 4 4c0 2.21-1.791 4-4 4zm6.406-11.845c-.796 0-1.441.645-1.441 1.44s.645 1.44 1.441 1.44c.795 0 1.439-.645 1.439-1.44s-.644-1.44-1.439-1.44z"/></svg>';
        var copySvg = '<svg class="share-svg" fill="currentColor" height="16" viewBox="0 0 24 24" width="16"><path d="M3.9 12c0-1.71 1.39-3.1 3.1-3.1h4V7H7c-2.76 0-5 2.24-5 5s2.24 5 5 5h4v-1.9H7c-1.71 0-3.1-1.39-3.1-3.1zM8 13h8v-2H8v2zm9-6h-4v1.9h4c1.71 0 3.1 1.39 3.1 3.1s-1.39 3.1-3.1 3.1h-4V17h4c2.76 0 5-2.24 5-5s-2.24-5-5-5z"/></svg>';

        var shareTop = '<div class="post-share-bar" id="post-share-top">' +
                       '<span class="share-bar-label">&#128227; <b>Share Post:</b></span>' +
                       '<div class="share-btn-group">' +
