                            '<button class="share-btn btn-fb share-btn-lg" onclick="sharePostTo(\'facebook\')" type="button">' + fbSvg + ' <span>Share on Facebook</span></button>' +
                            '<button class="share-btn btn-tg share-btn-lg" onclick="sharePostTo(\'telegram\')" type="button">' + tgSvg + ' <span>Share on Telegram</span></button>' +
