        directBox.innerHTML = rendered;
        setCache('post_' + currentPath, rendered);
      }
    }).catch(function() {});

    loadAllPostsProgressively();
    setupLiveSearch();
    return;
  }

  // LABEL ARCHIVE LOADER (PAGINATES THROUGH ALL POSTS IN CATEGORY)
  if (isLabelPage) {
    var rawCat = window.location.pathname.split('/search/label/')[1].split('?')[0];
    var catName = decodeURIComponent(rawCat).replace(/\+/g, ' ').trim();
    var catNameLower = catName.toLowerCase();

    var catContainer = document.getElementById('category-view-container');
    var catTitle = document.getElementById('archive-category-title');
    var itemsList = document.getElementById('archive-items-list');
    var paginationBox = document.getElementById('archive-pagination');

    if (catContainer) catContainer.style.display = 'block';
    if (catTitle) catTitle.innerText = catName + ' Updates (Loading...)';

    var allFilteredPosts = [];
    var perPage = 30;
    var currentArchivePage = 1;

    function renderArchivePage(page) {
      currentArchivePage = page;
      var total = allFilteredPosts.length;
      var totalPages = Math.ceil(total / perPage) || 1;
      var start = (page - 1) * perPage;
      var end = Math.min(start + perPage, total);

      var listHtml = '';
      for (var i = start; i < end; i++) {
        var badges = getSmartBadges(allFilteredPosts[i].title);
        var safeTitle = allFilteredPosts[i].title.replace(/'/g, "\\'");
        listHtml += '<li style="padding:10px 4px; border-bottom:1px solid var(--border); display:flex; align-items:center; gap:8px;">' +
                    badges.org +
                    '<a href="' + allFilteredPosts[i].link + '" style="font-weight:600; flex:1;">' + allFilteredPosts[i].title + '</a>' +
                    badges.urgency +
                    '<button class="btn-item-share" onclick="shareToWhatsApp(\'' + safeTitle + '\', \'' + allFilteredPosts[i].link + '\')" title="Share to WhatsApp">💬</button>' +
                    '</li>';
      }
      if (itemsList) itemsList.innerHTML = listHtml || '<li>No records found in this category.</li>';

      var pagHtml = '';
      if (totalPages > 1) {
        pagHtml += '<button ' + (page === 1 ? 'disabled' : '') + ' onclick="window._goCatPage(' + (page - 1) + ')" style="padding:6px 12px; border:1px solid var(--border); border-radius:6px; background:var(--surface); cursor:pointer;">« Prev</button>';
        for (var p = 1; p <= totalPages; p++) {
          if (p === 1 || p === totalPages || (p >= page - 2 && p <= page + 2)) {
            pagHtml += '<button class="' + (p === page ? 'active' : '') + '" onclick="window._goCatPage(' + p + ')" style="padding:6px 12px; border:1px solid var(--border); border-radius:6px; background:' + (p === page ? 'var(--brand)' : 'var(--surface)') + '; color:' + (p === page ? '#fff' : 'inherit') + '; cursor:pointer; font-weight:700;">' + p + '</button>';
          }
        }
        pagHtml += '<button ' + (page === totalPages ? 'disabled' : '') + ' onclick="window._goCatPage(' + (page + 1) + ')" style="padding:6px 12px; border:1px solid var(--border); border-radius:6px; background:var(--surface); cursor:pointer;">Next »</button>';
      }
      if (paginationBox) paginationBox.innerHTML = pagHtml;
    }

    window._goCatPage = function(p) {
      renderArchivePage(p);
      window.scrollTo({ top: 120, behavior: 'smooth' });
    };

    function fetchCategoryBatches(startIndex) {
      var labelUrl = '/feeds/posts/summary/-/' + encodeURIComponent(catName) + '?alt=json&start-index=' + startIndex + '&max-results=100';
      fetch(labelUrl)
        .then(function(res) { return res.json(); })
        .then(function(data) {
          var raw = (data.feed && data.feed.entry) ? data.feed.entry : [];
          var parsed = parseFeedEntries(raw);
          allFilteredPosts = allFilteredPosts.concat(parsed);

          if (catTitle) {
            catTitle.innerText = catName + ' — ' + allFilteredPosts.length + ' Updates';
          }
          renderArchivePage(currentArchivePage);

          if (raw.length >= 90) {
            fetchCategoryBatches(startIndex + raw.length);
          } else {
            if (catTitle) {
              catTitle.innerText = catName + ' — All ' + allFilteredPosts.length + ' Verified Updates';
            }
            renderArchivePage(currentArchivePage);
          }
        })
        .catch(function(err) {
          if (allFilteredPosts.length === 0) {
            loadAllPostsProgressively(function(all) {
              allFilteredPosts = all.filter(function(item) {
                var tl = item.title.toLowerCase();
                if (item.categories && item.categories.indexOf(catNameLower) > -1) return true;
                if (catNameLower === 'latest jobs' && (item.cat === 'Job' || tl.indexOf('online form') > -1)) return true;
                if (catNameLower === 'result' && (item.cat === 'Result' || tl.indexOf('result') > -1)) return true;
                if (catNameLower === 'admit card' && (item.cat === 'Admit Card' || tl.indexOf('admit') > -1)) return true;
                if (catNameLower === 'answer key' && (item.cat === 'Answer Key' || tl.indexOf('answer key') > -1)) return true;
                if (catNameLower === 'syllabus' && (item.cat === 'Syllabus' || tl.indexOf('syllabus') > -1)) return true;
                return false;
              });
              if (catTitle) catTitle.innerText = catName + ' — All ' + allFilteredPosts.length + ' Verified Updates';
              renderArchivePage(1);
            });
          }
        });
    }

    fetchCategoryBatches(1);
    loadAllPostsProgressively(); // Index all 400+ posts for top search
    setupLiveSearch();
    return;
  }

  // HOMEPAGE FEED LOADER (PROGRESSIVE MULTI-BATCH FOR ALL 400+ POSTS)
  if (currentPath === '' || currentPath === '/') {
    var cachedEntries = getCache('sr_all_posts_v4');
    if (cachedEntries && cachedEntries.length > 0) {
      globalAllPosts = cachedEntries;
      rawFeedEntries = cachedEntries;
      renderHomepageBoxes('ALL');
      updateCategoryLiveCounts(cachedEntries);
      setupLiveSearch();
    } else {
      injectSkeletons();
    }

    loadAllPostsProgressively(
      function onFirstBatch(firstBatch) {
        renderHomepageBoxes('ALL');
        setupLiveSearch();
      },
      function onProgress(accumulated) {
        updateCategoryLiveCounts(accumulated);
      },
      function onAllDone(allPosts) {
        renderHomepageBoxes('ALL');
        updateCategoryLiveCounts(allPosts);
        setupLiveSearch();
      }
    );
  }
})();

// 9. PHOTO & SIGNATURE RESIZER TOOL ENGINE
(function() {
  const fileIn = document.getElementById('toolImgInput');
  const wIn = document.getElementById('toolWidth');
  const hIn = document.getElementById('toolHeight');
  const kbIn = document.getElementById('toolMaxKB');
  const btn = document.getElementById('toolProcessBtn');
  const resBox = document.getElementById('toolResult');
  const prev = document.getElementById('toolPreview');
  const meta = document.getElementById('toolMeta');
  const dl = document.getElementById('toolDownload');

  let currentImg = new Image();

  if (fileIn) {
    fileIn.addEventListener('change', function(e) {
      const file = e.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = function(evt) {
          currentImg.onload = function() {
            wIn.value = currentImg.naturalWidth;
            hIn.value = currentImg.naturalHeight;
          };
          currentImg.src = evt.target.result;
        };
        reader.readAsDataURL(file);
      }
    });
  }

  if (btn) {
    btn.addEventListener('click', function() {
      if (!currentImg.src || !fileIn.files[0]) {
        alert('Kripya pehle image file select karein.');
        return;
      }

      const targetW = parseInt(wIn.value) || currentImg.naturalWidth;
      const targetH = parseInt(hIn.value) || currentImg.naturalHeight;
      const maxKB = parseFloat(kbIn.value);

      const canvas = document.createElement('canvas');
      canvas.width = targetW;
      canvas.height = targetH;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(currentImg, 0, 0, targetW, targetH);

      let quality = 0.92;
      let dataUrl = canvas.toDataURL('image/jpeg', quality);

      if (maxKB) {
        while (quality > 0.08) {
          const currentKB = (dataUrl.length * (3/4)) / 1024;
          if (currentKB <= maxKB) break;
          quality -= 0.08;
          dataUrl = canvas.toDataURL('image/jpeg', quality);
        }
      }

      const finalKB = ((dataUrl.length * (3/4)) / 1024).toFixed(1);
      prev.src = dataUrl;
      dl.href = dataUrl;
      meta.innerText = 'Size: ' + targetW + 'x' + targetH + ' px | File Size: ' + finalKB + ' KB';
      resBox.style.display = 'block';
    });
  }
})();

// 10. HELPER BANNER INJECTION ON POSTS
(function injectResizerBanner() {
  if (window.location.pathname === '/' || window.location.pathname.indexOf('/p/') !== -1) {
    return;
  }

  var attempts = 0;
  var interval = setInterval(function() {
    attempts++;
    var container = document.getElementById('direct-post-display') || 
                    document.querySelector('.content-body-area') || 
                    document.querySelector('.post-body');

    if (container && (container.innerText.length > 50 || container.children.length > 0)) {
      if (!document.getElementById('sr-resizer-banner')) {
        var banner = document.createElement('div');
        banner.id = 'sr-resizer-banner';
        banner.style.cssText = 'background: #eff6ff; border: 1px solid #bfdbfe; border-left: 5px solid #2563eb; padding: 14px 18px; margin: 25px auto 15px auto; border-radius: 8px; font-family: inherit; max-width: 95%; box-sizing: border-box;';
        banner.innerHTML = '<p style="margin: 0; font-size: 14px; color: #1e3a8a; line-height: 1.5;">' +
          '📌 <b>Online Form Helper:</b> Is bharti ka online form bharte waqt photo aur signature resize karne ke liye hamara ' +
          '<a href="/p/photo-signature-resizer.html" target="_blank" style="color: #2563eb; font-weight: bold; text-decoration: underline;">Online Photo &amp; Signature Resizer Tool</a> 100% Free use karein.' +
          '</p>';
        container.appendChild(banner);
      }
      clearInterval(interval);
    }

    if (attempts > 30) {
      clearInterval(interval);
    }
  }, 500);
})();
